const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Files</h1>\n        <p class=\"subtitle\" id=\"filesSub\"></p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card fx-card-outer\">\n      <div class=\"fx\" id=\"fx\">\n        <aside class=\"fx-side\" id=\"fxSide\">\n          <label class=\"fx-search\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n            <input type=\"search\" id=\"fxSearch\" placeholder=\"Search all files\" autocomplete=\"off\" aria-label=\"Search all files\">\n          </label>\n          <nav class=\"fx-nav\" id=\"fxNav\" aria-label=\"Show files from\"></nav>\n        </aside>\n        <section class=\"fx-main\" id=\"fxMain\" aria-live=\"polite\"></section>\n      </div>\n    </div>\n    <div class=\"fx-menu\" id=\"fxMenu\" role=\"menu\" hidden></div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  \n  \n";
const SCRIPT_JS = "\n    // ---- Links by id (2026-10-07, Martin) ----\n    // A real class (Schoology/Classroom ids are digits) links as\n    // assignment?id=<id> and course-home?id=<section id>; the sample classes\n    // (word ids like \"apchem\") keep ?course=&title=. Pages read both.\n    function avgIsId(v) { return /^\\d{1,24}$/.test(String(v == null ? '' : v)); }\n    function avgCourseQ(course) { return (avgIsId(course) ? 'id=' : 'course=') + encodeURIComponent(course == null ? '' : course); }\n    function avgAssignHref(course, title, id, extra) {\n      extra = extra || '';\n      if (avgIsId(id) && avgIsId(course)) return `/assignment?id=${id}${extra}`;\n      return `/assignment?course=${encodeURIComponent(course == null ? '' : course)}&title=${encodeURIComponent(title || '')}${avgIsId(id) ? `&id=${id}` : ''}${extra}`;\n    }\n\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Files (2026-10-04, per Martin). Every course's files in one place,\n    // plus the Google Drive files a student added or made with Averages\n    // (drive.file only, never their whole Drive) and their Canva designs.\n    //\n    // Sample data for the preview only. Signed in (LegacyPage.tsx sets\n    // window.__AVERAGES_MODE__) a student never sees these samples: live\n    // mode shows the same layout with their real course files, Google\n    // Drive, OneDrive and Canva files instead (liveFiles below).\n    // FILE_COURSES (not COURSES) on purpose, so scripts/port-pages.mjs\n    // doesn't swap in live course data next to sample files.\n    // ------------------------------------------------------------------\n    const FILES_SIGNED_IN = !!window.__AVERAGES_MODE__;\n    const FILE_COURSES = [\n      { id: 'apchem', name: 'AP Chemistry', color: '#a67a22' },\n      { id: 'algebra2', name: 'Algebra II', color: '#5b6ea3' },\n      { id: 'english10', name: 'English 10', color: '#6b8f5e' },\n      { id: 'ushistory', name: 'U.S. History', color: '#a15c4f' },\n      { id: 'spanish3', name: 'Spanish III', color: '#8a6ba1' },\n    ];\n    // date: when it last changed. src: 'course' | 'gdrive' | 'canva'.\n    const FILES = [\n      { name: 'Molarity Worksheet.docx', type: 'docx', src: 'course', course: 'apchem', date: '2026-08-22' },\n      { name: 'Lab Report #4.pdf', type: 'pdf', src: 'course', course: 'apchem', date: '2026-08-18' },\n      { name: 'Mole Conversions Slides.pptx', type: 'pptx', src: 'course', course: 'apchem', date: '2026-08-14' },\n      { name: 'Lab Safety Contract.pdf', type: 'pdf', src: 'course', course: 'apchem', date: '2026-08-03' },\n      { name: 'Syllabus.pdf', type: 'pdf', src: 'course', course: 'apchem', date: '2026-08-01' },\n      { name: 'Factoring Review Slides.pptx', type: 'pptx', src: 'course', course: 'algebra2', date: '2026-08-21' },\n      { name: 'Elimination Method Practice.docx', type: 'docx', src: 'course', course: 'algebra2', date: '2026-08-14' },\n      { name: 'Formula Sheet.pdf', type: 'pdf', src: 'course', course: 'algebra2', date: '2026-08-01' },\n      { name: 'Discussion Questions.pdf', type: 'pdf', src: 'course', course: 'english10', date: '2026-08-23' },\n      { name: 'The Lottery.pdf', type: 'pdf', src: 'course', course: 'english10', date: '2026-08-10' },\n      { name: 'MLA Format Guide.pdf', type: 'pdf', src: 'course', course: 'english10', date: '2026-08-01' },\n      { name: 'Timeline Project Instructions.pdf', type: 'pdf', src: 'course', course: 'ushistory', date: '2026-08-18' },\n      { name: 'Jamestown Reading.pdf', type: 'pdf', src: 'course', course: 'ushistory', date: '2026-08-05' },\n      { name: 'Unit 3 Vocab List.pdf', type: 'pdf', src: 'course', course: 'spanish3', date: '2026-08-20' },\n      { name: 'Verb Conjugation Chart.pdf', type: 'pdf', src: 'course', course: 'spanish3', date: '2026-08-01' },\n      { name: 'History Essay Draft', type: 'doc', src: 'gdrive', date: '2026-08-23', kind: 'Docs' },\n      { name: 'Lab Report Template', type: 'doc', src: 'gdrive', date: '2026-08-18', kind: 'Docs', made: true },\n      { name: 'Titration Lab Data', type: 'sheet', src: 'gdrive', date: '2026-08-17', kind: 'Sheets' },\n      { name: 'Spanish Presentation', type: 'slides', src: 'gdrive', date: '2026-08-15', kind: 'Slides' },\n      { name: 'Study Schedule', type: 'sheet', src: 'gdrive', date: '2026-08-09', kind: 'Sheets' },\n      { name: 'Essay Outline.docx', type: 'docx', src: 'onedrive', date: '2026-08-20' },\n      { name: 'Science Fair Data.xlsx', type: 'xlsx', src: 'onedrive', date: '2026-08-13' },\n      { name: 'Spanish Project.pptx', type: 'pptx', src: 'onedrive', date: '2026-08-07' },\n      { name: 'Molarity Practice Set', type: 'canva', src: 'canva', date: '2026-08-24' },\n      { name: 'Spanish Vocab Flashcards', type: 'canva', src: 'canva', date: '2026-08-16' },\n      { name: 'Colonial Timeline Poster', type: 'canva', src: 'canva', date: '2026-08-12' },\n      { name: 'Science Fair Board', type: 'canva', src: 'canva', date: '2026-08-08' },\n    ];\n    const FILES_TODAY = new Date(2026, 7, 24);   // the demo's Monday, Aug 24\n    const BADGE = { pdf: ['PDF', '#c1443a'], docx: ['DOCX', '#3b6fd1'], pptx: ['PPTX', '#d1852f'], doc: ['DOC', '#3b6fd1'], sheet: ['SHEET', '#2f7d54'], slides: ['SLIDES', '#d1852f'], xlsx: ['XLSX', '#2f7d54'] };\n    const THUMB = { pdf: '#f1dcd9', docx: '#dbe4f7', doc: '#dbe4f7', pptx: '#f6e6d2', slides: '#f6e6d2', sheet: '#dcebe1', xlsx: '#dcebe1' };\n    const SRC_NAME = { course: 'Course Files', gdrive: 'Google Drive', onedrive: 'OneDrive', canva: 'Canva' };\n    // Assignments a file can be attached to (sample: /assignment's\n    // overdue, upcoming and returned work; tests are turned in on Schoology\n    // and discussions are posts, so neither is listed).\n    const ATTACH_TARGETS = [\n      { title: 'Lab Report #4', course: 'apchem', when: 'Late' },\n      { title: 'Titration Lab Prep', course: 'apchem', when: 'Due Mon, Aug 24' },\n      { title: 'Vocab Worksheet', course: 'spanish3', when: 'Due Tue, Aug 25' },\n      { title: 'Problem Set 7', course: 'algebra2', when: 'Due Wed, Aug 26' },\n      { title: 'Periodic Trends Worksheet', course: 'apchem', when: 'Returned' },\n    ];\n    const CHEV_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6l6 6-6 6\"/></svg>';\n    const MORE_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"12\" r=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/><circle cx=\"19\" cy=\"12\" r=\"2\"/></svg>';\n    const esc = v => String(v == null ? '' : v).replace(/[&<>\"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]));\n    const courseOf = id => FILE_COURSES.find(c => c.id === id);\n    function ymdDate(s) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }\n    function daysAgo(f) { return Math.round((FILES_TODAY - ymdDate(f.date)) / 86400000); }\n    function whenLabel(f) {\n      const n = daysAgo(f);\n      if (n <= 0) return 'Today';\n      if (n === 1) return 'Yesterday';\n      return ymdDate(f.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });\n    }\n    function fromLabel(f) {\n      if (f.src === 'course') { const c = courseOf(f.course); return c ? c.name : 'Course'; }\n      return SRC_NAME[f.src];\n    }\n    function fromHTML(f) {\n      if (f.src === 'course') { const c = courseOf(f.course); return `<span class=\"fx-dot\" style=\"background:${esc(c ? c.color : '#888')}\"></span>${esc(c ? c.name : 'Course')}`; }\n      return esc(SRC_NAME[f.src]);\n    }\n    // New file icons (2026-10-09, public/js/averages-file-icons.js); the old badge if that script isn't loaded.\n    const AVFI = () => window.AveragesFileIcons || null;\n    function badgeHTML(f) {\n      if (AVFI()) return AVFI().html(f.type, { size: 34 });\n      if (f.type === 'canva') return '<span class=\"fx-badge canva\" aria-hidden=\"true\"><span class=\"cm\"></span></span>';\n      const b = BADGE[f.type] || ['FILE', '#83849a'];\n      return `<span class=\"fx-badge\" aria-hidden=\"true\" style=\"background:${b[1]}\">${b[0]}</span>`;\n    }\n\n    let fxFilter = 'all';\n    let fxQuery = '';\n    let fxView = 'list';\n    try { if (localStorage.getItem('schoolagy_files_view') === 'grid') fxView = 'grid'; } catch {}\n    FILES.forEach((f, i) => { f.id = 'f' + i; });\n\n    function inFilter(f, filter) {\n      if (filter === 'all') return true;\n      if (filter === 'recent') return daysAgo(f) <= 7;\n      if (filter === 'course' || filter === 'gdrive' || filter === 'onedrive' || filter === 'canva') return f.src === filter;\n      if (filter.startsWith('c:')) return f.src === 'course' && f.course === filter.slice(2);\n      return true;\n    }\n    function matches(f) {\n      if (!fxQuery) return true;\n      const hay = `${f.name} ${fromLabel(f)} ${f.kind || ''}`.toLowerCase();\n      return hay.includes(fxQuery);\n    }\n    function filterTitle() {\n      if (fxFilter === 'all') return 'All Files';\n      if (fxFilter === 'recent') return 'Recents';\n      if (fxFilter.startsWith('c:')) { const c = courseOf(fxFilter.slice(2)); return c ? c.name : 'Course'; }\n      return SRC_NAME[fxFilter];\n    }\n    const byNewest = (a, b) => b.date.localeCompare(a.date) || a.name.localeCompare(b.name);\n\n    function renderNav() {\n      const count = filter => FILES.filter(f => inFilter(f, filter)).length;\n      const item = (filter, label, extra) => `<button class=\"fx-item${fxFilter === filter ? ' on' : ''}\" type=\"button\" data-filter=\"${esc(filter)}\" aria-current=\"${fxFilter === filter ? 'true' : 'false'}\">${extra || ''}<span class=\"nm\">${esc(label)}</span><span class=\"n\">${count(filter)}</span></button>`;\n      document.getElementById('fxNav').innerHTML =\n        item('all', 'All Files') + item('recent', 'Recents') +\n        '<p class=\"fx-label\">Sources</p>' + item('course', 'Course Files') + item('gdrive', 'Google Drive') + item('onedrive', 'OneDrive') + item('canva', 'Canva') +\n        '<p class=\"fx-label\">Courses</p>' + FILE_COURSES.map(c => item('c:' + c.id, c.name, `<span class=\"fx-dot\" style=\"background:${esc(c.color)}\"></span>`)).join('');\n    }\n    function tileHTML(f) {\n      const thumb = f.type === 'canva'\n        ? '<span class=\"fx-thumb canva\" style=\"background:linear-gradient(135deg,#7d2ae7,#00c4cc)\"><span class=\"page\"><i></i><i></i><i></i></span></span>'\n        : AVFI() ? `<span class=\"fx-thumb avfi-thumb\" style=\"background:${AVFI().color(f.type)}14\">${AVFI().html(f.type, { size: 64 })}</span>`\n        : `<span class=\"fx-thumb\" style=\"background:${THUMB[f.type] || '#e4e4e8'}\"><span class=\"page\"><i></i><i></i><i></i><i></i><i></i></span></span>`;\n      const src = f.src === 'canva' ? 'Canva' : f.src === 'gdrive' ? `Google Drive · ${esc(f.kind || 'File')}` : fromHTML(f);\n      return `<button class=\"fx-tile\" type=\"button\" data-file=\"${f.id}\" aria-label=\"${esc(f.name)}, ${esc(fromLabel(f))}\">${thumb}<span class=\"fx-tile-name\">${esc(f.name)}</span><span class=\"fx-tile-src\">${src}</span></button>`;\n    }\n    function rowHTML(f) {\n      return `<div class=\"fx-row\" role=\"row\" tabindex=\"0\" data-file=\"${f.id}\" aria-label=\"${esc(f.name)}, ${esc(fromLabel(f))}, changed ${esc(whenLabel(f))}\">\n          ${badgeHTML(f)}\n          <span class=\"fx-name\"><span>${esc(f.name)}</span><small>${esc(fromLabel(f))} · ${esc(whenLabel(f))}</small></span>\n          <span class=\"fx-src\">${fromHTML(f)}</span>\n          <span class=\"fx-date\">${esc(whenLabel(f))}</span>\n          <button class=\"fx-more\" type=\"button\" data-more=\"${f.id}\" aria-label=\"More for ${esc(f.name)}\" aria-haspopup=\"menu\">${MORE_ICON}</button>\n        </div>`;\n    }\n    function render() {\n      renderNav();\n      const main = document.getElementById('fxMain');\n      const chips = [['all', 'All'], ['recent', 'Recents'], ['course', 'Courses'], ['gdrive', 'Google Drive'], ['onedrive', 'OneDrive'], ['canva', 'Canva']]\n        .map(([k, l]) => `<button class=\"fx-chip\" type=\"button\" data-filter=\"${k}\" aria-pressed=\"${fxFilter === k}\">${l}</button>`).join('');\n      const list = FILES.filter(f => inFilter(f, fxFilter) && matches(f)).sort(byNewest);\n      const showRecent = fxFilter === 'all' && !fxQuery && fxView === 'list';\n      let body = '';\n      if (!list.length) {\n        body = `<div class=\"fx-empty\"><strong>Nothing here</strong>${fxQuery ? `No files match \"${esc(fxQuery)}\".` : 'No files yet.'}</div>`;\n      } else {\n        if (showRecent) body += `<p class=\"fx-sec\">Recent</p><div class=\"fx-grid\">${list.slice(0, 4).map(tileHTML).join('')}</div>`;\n        body += `<p class=\"fx-sec\">${showRecent ? 'All files' : (fxQuery ? 'Results' : 'Files')}</p>`;\n        body += fxView === 'grid'\n          ? `<div class=\"fx-grid\">${list.map(tileHTML).join('')}</div>`\n          : `<div class=\"fx-list\" role=\"table\" aria-label=\"${esc(filterTitle())}\"><div class=\"fx-row head\" role=\"row\"><span></span><span>Name</span><span>From</span><span>Changed</span><span></span></div>${list.map(rowHTML).join('')}</div>`;\n      }\n      if (fxFilter === 'all' || fxFilter === 'gdrive' || fxFilter === 'onedrive') body += '<p class=\"fx-note\">Google Drive and OneDrive show the files you add here or make with Averages, not your whole drive.</p>';\n      main.innerHTML = `\n        <div class=\"fx-head\">\n          <h2>${esc(filterTitle())}</h2><span class=\"fx-meta\">${list.length} file${list.length === 1 ? '' : 's'}</span>\n          <div class=\"fx-tools\">\n            <div class=\"fx-seg\" role=\"group\" aria-label=\"View\">\n              <button type=\"button\" data-view=\"list\" aria-pressed=\"${fxView === 'list'}\">List</button>\n              <button type=\"button\" data-view=\"grid\" aria-pressed=\"${fxView === 'grid'}\">Grid</button>\n            </div>\n            <button class=\"fx-add\" type=\"button\" id=\"fxAddDrive\" aria-haspopup=\"menu\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>Add files</button>\n          </div>\n        </div>\n        <div class=\"fx-chips\" role=\"group\" aria-label=\"Show files from\">${chips}</div>\n        ${body}`;\n      document.getElementById('filesSub').textContent = `${FILES.length} files from ${FILE_COURSES.length} courses, Google Drive, OneDrive and Canva`;\n    }\n\n    // Menus: a file's actions, and Add from Google Drive.\n    const fxMenu = document.getElementById('fxMenu');\n    let fxMenuFor = null;\n    let fxLast = null;   // where the last menu opened, so a submenu opens in the same spot\n    function closeFxMenu(focusBack) {\n      if (fxMenu.hidden) return;\n      fxMenu.hidden = true;\n      if (fxMenuFor) { fxMenuFor.setAttribute('aria-expanded', 'false'); if (focusBack && document.body.contains(fxMenuFor)) fxMenuFor.focus(); }\n      fxMenuFor = null;\n    }\n    // `at` is an optional { x, y } point: a right-click opens the menu at the\n    // cursor instead of under the anchor.\n    function openFxMenu(anchor, label, items, at) {\n      if (fxMenuFor === anchor && !at) { closeFxMenu(true); return; }\n      closeFxMenu(false);\n      // The Attach chooser (2026-10-06): `group` heads each class, `note` says there's nothing to pick.\n      fxMenu.innerHTML = `<div class=\"fx-menu-label\">${esc(label)}</div>` + items.map((it, i) =>\n        it.group ? `<div class=\"fx-menu-group\" role=\"presentation\">${it.color ? `<span class=\"fx-dot\" style=\"background:${esc(it.color)}\"></span>` : ''}<span>${esc(it.group)}</span></div>`\n        : it.note ? `<div class=\"fx-menu-note\" role=\"presentation\">${esc(it.note)}</div>`\n        : `<button class=\"fx-menu-item\" type=\"button\" role=\"menuitem\" data-i=\"${i}\"${it.soon ? ' disabled' : ''}><span>${esc(it.label)}${it.sub ? `<small>${esc(it.sub)}</small>` : ''}</span>${it.soon ? '<span class=\"fx-soon\">Coming soon</span>' : it.next ? `<span class=\"fx-next\">${CHEV_ICON}</span>` : ''}</button>`).join('');\n      fxMenu.querySelectorAll('.fx-menu-item').forEach(b => b.addEventListener('click', () => { const it = items[+b.dataset.i]; closeFxMenu(false); if (it.run) it.run(); }));\n      fxMenu.hidden = false;\n      fxMenu.style.left = '0px'; fxMenu.style.top = '0px';\n      const r = anchor.getBoundingClientRect(), w = fxMenu.offsetWidth, h = fxMenu.offsetHeight;\n      const nav = document.querySelector('.app-nav');\n      const floor = Math.min(window.innerHeight, nav ? nav.getBoundingClientRect().top : window.innerHeight) - 8;\n      if (at) {\n        fxMenu.style.left = Math.max(8, Math.min(at.x, window.innerWidth - w - 8)) + 'px';\n        fxMenu.style.top = Math.max(8, at.y + h > floor ? at.y - h : at.y) + 'px';\n      } else {\n        fxMenu.style.left = Math.max(8, Math.min(r.right - w, window.innerWidth - w - 8)) + 'px';\n        fxMenu.style.top = (r.bottom + 6 + h > floor ? Math.max(8, r.top - h - 6) : r.bottom + 6) + 'px';\n      }\n      anchor.setAttribute('aria-expanded', 'true');\n      fxMenuFor = anchor;\n      fxLast = { anchor, x: parseFloat(fxMenu.style.left), y: parseFloat(fxMenu.style.top) };\n      const first = fxMenu.querySelector('.fx-menu-item:not(:disabled)');\n      if (first) first.focus();\n    }\n    // ------------------------------------------------------------------\n    // Signed in (2026-10-06, per Martin: \"can you go back to the old\n    // version\"): the same layout as the preview, with real files. One list\n    // across course files, Google Drive, OneDrive and Canva, newest first,\n    // with Recents, the sidebar (All Files, Recents, Sources, Courses),\n    // search and List/Grid. Each source fills in as it loads, so a slow one\n    // never holds the page up. Picking Canva in the sidebar shows the\n    // student's Canva folders when that's switched on (GET /canva/status's\n    // `folders`).\n    // Google Drive and OneDrive run in this browser (public/js/averages-cloud.js)\n    // and only ever see the files Averages.io made or the student picked:\n    // Google's drive.file permission, and OneDrive's Averages.io folder.\n    // ------------------------------------------------------------------\n    function liveFiles() {\n      const api = window.location.hostname.endsWith('averages.io') ? 'https://api.averages.io' : 'http://localhost:8787';\n      const CANVA_EDIT_URL = /^https:\\/\\/(www\\.)?canva\\.com\\//i;\n      const main = document.getElementById('fxMain');\n      const fxRoot = document.getElementById('fx');\n      // Incognito (2026-10-05, set by LegacyPage.tsx): connected apps are off.\n      const INCOGNITO = !!(window.__AVERAGES_INCOGNITO__ && window.__AVERAGES_INCOGNITO__.on);\n      const DAY = 86400000;\n      const RECENT_DAYS = 7;\n      const dayLabel = ms => {\n        const t = Number(ms) || 0;\n        if (!t) return '';\n        const days = Math.floor((Date.now() - t) / DAY);\n        if (days <= 0) return 'Today';\n        if (days === 1) return 'Yesterday';\n        return new Date(t).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });\n      };\n      // Google Docs, Sheets and Slides and Canva designs have no file size, so they count as 0.\n      function sizeLabel(bytes) {\n        const mb = bytes / (1024 * 1024);\n        if (!bytes) return '0 MB';\n        if (mb < 0.1) return '0.1 MB';\n        if (mb >= 1024) return `${(mb / 1024).toFixed(1)} GB`;\n        if (mb >= 10) return `${Math.round(mb)} MB`;\n        return `${mb.toFixed(1)} MB`;\n      }\n      const PLUS_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>';\n      const FOLDER_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 7.5V18a1.5 1.5 0 0 0 1.5 1.5h15A1.5 1.5 0 0 0 21 18V9a1.5 1.5 0 0 0-1.5-1.5h-7.4L10 5H4.5A1.5 1.5 0 0 0 3 6.5z\"/></svg>';\n\n      // The page's own state.\n      const LV = { filter: 'all', query: '', shown: 60 };\n\n      // ---------- Google Drive and OneDrive ----------\n      const CLOUD = {\n        gdrive: { name: 'Google Drive', state: 'loading', files: [], busy: false, message: '' },\n        onedrive: { name: 'OneDrive', state: 'loading', files: [], busy: false, message: '' },\n      };\n      let cfg = null;\n      const C = () => window.AveragesCloud || null;\n      const G_TYPE = {\n        'application/vnd.google-apps.document': ['doc', 'Docs'],\n        'application/vnd.google-apps.spreadsheet': ['sheet', 'Sheets'],\n        'application/vnd.google-apps.presentation': ['slides', 'Slides'],\n        'application/pdf': ['pdf', 'PDF'],\n      };\n      function typeOf(name, mime) {\n        if (G_TYPE[mime]) return G_TYPE[mime];\n        const m = String(name || '').match(/\\.([a-z0-9]{1,6})$/i);\n        const ext = m ? m[1].toLowerCase() : 'file';\n        return [ext, ext.toUpperCase()];\n      }\n      function normalize(app, f) {\n        if (app === 'gdrive') {\n          const [type, kind] = typeOf(f.name, f.mimeType);\n          // thumbnailLink (2026-10-07): Google's own short-lived preview image, when it has one.\n          return { id: String(f.id || ''), name: String(f.name || 'Untitled'), type, kind, url: String(f.webViewLink || ''), t: Date.parse(f.modifiedTime) || 0, size: Number(f.size) || 0, thumb: String(f.thumbnailLink || '') };\n        }\n        const [type, kind] = typeOf(f.name, '');\n        return { id: String(f.id || ''), name: String(f.name || 'Untitled'), type, kind, url: String(f.webUrl || ''), t: Date.parse(f.lastModifiedDateTime) || 0, picked: !!f.picked, size: Number(f.size) || 0 };\n      }\n      // Add from Google Drive / OneDrive needs the Picker key (Google) or the app id (Microsoft).\n      const canPick = app => (app === 'gdrive' ? !!(cfg && cfg.google && cfg.google.apiKey && cfg.google.appId) : !!(cfg && cfg.microsoft));\n      async function listCloud(app, token) {\n        const c = CLOUD[app];\n        c.state = 'loading';\n        render();\n        try {\n          const raw = app === 'gdrive' ? await C().googleList(token) : await C().oneDriveList(token);\n          c.files = raw.map(f => normalize(app, f)).sort((a, b) => b.t - a.t);\n          c.state = 'ready';\n        } catch (err) {\n          c.state = err && err.code === 'needs_click' ? 'click' : 'error';\n          c.message = C().messageFor(err);\n        }\n        render();\n      }\n      /** On page load: list right away when this tab can, without opening anything. */\n      function startCloud(app) {\n        const c = CLOUD[app];\n        const configured = app === 'gdrive' ? !!cfg.google : !!cfg.microsoft;\n        if (!configured) { c.state = 'soon'; render(); return; }\n        if (!C().accounts()[app]) { c.state = 'connect'; render(); return; }\n        const quiet = app === 'gdrive' ? C().googleToken({}) : C().oneDriveToken({});\n        quiet.then(t => listCloud(app, t), () => { c.state = 'click'; render(); });\n      }\n      /** Connect / Show files / Add: asks for the token inside the click, then lists. */\n      function askCloud(app, how) {\n        const c = CLOUD[app];\n        const K = C();\n        if (!K) return;\n        let pending;\n        if (app === 'gdrive') {\n          if (!K.googleReady()) {\n            K.prepareGoogle().catch(() => {});\n            c.state = 'error'; c.message = K.messageFor('not_ready'); render();\n            return;\n          }\n          pending = how === 'connect' ? K.connectGoogle().then(() => K.googleToken({})) : K.googleSession({ interactive: true });\n        } else if (how === 'pick') {\n          // Read-only access is asked for here (the first time) and nowhere else.\n          pending = K.oneDriveToken({ interactive: true, read: true });\n        } else {\n          pending = how === 'connect' ? K.connectOneDrive().then(() => K.oneDriveToken({})) : K.oneDriveToken({ interactive: true });\n        }\n        c.busy = true;\n        render();\n        pending\n          .then(async token => {\n            if (how === 'pick') {\n              const picked = app === 'gdrive' ? await K.googlePick(token) : await K.oneDrivePick(token);\n              if (!picked.length && c.state === 'ready') return;\n              await listCloud(app, token);\n              // 2026-10-08: say what was added, and show a picked Google file\n              // even if Drive's list hasn't caught up with it yet.\n              if (picked.length && c.state === 'ready') {\n                if (app === 'gdrive') {\n                  const have = new Set(c.files.map(f => f.id));\n                  picked.forEach(d => { if (d && d.file && d.file.id && !have.has(String(d.file.id))) c.files.unshift(normalize(app, d.file)); });\n                }\n                flash(`Added ${picked.length} file${picked.length === 1 ? '' : 's'} from ${c.name}.`);\n              }\n              return;\n            }\n            await listCloud(app, token);\n          })\n          .catch(err => {\n            if (err && err.code === 'popup_closed') return;\n            c.state = 'error';\n            c.message = K.messageFor(err);\n          })\n          .finally(() => { c.busy = false; render(); });\n      }\n      function loadCloudScript() {\n        return new Promise((resolve, reject) => {\n          if (window.AveragesCloud) { resolve(window.AveragesCloud); return; }\n          const sc = document.createElement('script');\n          sc.src = '/js/averages-cloud.js';\n          sc.onload = () => (window.AveragesCloud ? resolve(window.AveragesCloud) : reject(new Error('cloud')));\n          sc.onerror = () => reject(new Error('cloud'));\n          document.head.appendChild(sc);\n        });\n      }\n      async function loadCloud() {\n        Object.keys(CLOUD).forEach(app => { CLOUD[app].state = 'loading'; });\n        render();\n        try {\n          const K = await loadCloudScript();\n          const c = await K.config();\n          if (c.failed) throw new Error('config');\n          cfg = c;\n          if (cfg.google) K.prepareGoogle().catch(() => {});\n          startCloud('gdrive');\n          startCloud('onedrive');\n        } catch {\n          Object.keys(CLOUD).forEach(app => { CLOUD[app].state = 'error'; CLOUD[app].message = 'Try again in a moment.'; });\n          render();\n        }\n      }\n\n      // ---------- Course files (2026-10-05) ----------\n      // Every file in the student's classes: what teachers posted in\n      // Materials and what's attached to assignments (GET /data/files, ids and\n      // names only). Download goes through the API; Save to Google Drive /\n      // OneDrive copies it into their drive from this browser.\n      const CF = { state: 'loading', courses: [], files: [], partial: false, classroom: false };\n      const CF_BADGE = { pdf: ['PDF', '#c1443a'], doc: ['DOC', '#3b6fd1'], docx: ['DOCX', '#3b6fd1'], ppt: ['PPT', '#d1852f'], pptx: ['PPTX', '#d1852f'], xls: ['XLS', '#2f7d54'], xlsx: ['XLSX', '#2f7d54'], csv: ['CSV', '#2f7d54'], png: ['PNG', '#7a5ba6'], jpg: ['JPG', '#7a5ba6'], jpeg: ['JPG', '#7a5ba6'], gif: ['GIF', '#7a5ba6'], txt: ['TXT', '#83849a'], zip: ['ZIP', '#83849a'] };\n      const ID_OK = v => /^\\d{1,24}$/.test(String(v || ''));\n      // Google Classroom (2026-10-05): its files are Google Drive files, listed with their Drive link.\n      const DRIVE_ID_OK = v => /^[A-Za-z0-9_-]{10,128}$/.test(String(v || ''));\n      const DRIVE_URL_OK = u => /^https:\\/\\/(drive|docs)\\.google\\.com\\//.test(String(u || ''));\n      Object.assign(CF_BADGE, { gdoc: ['DOC', '#3b6fd1'], gsheet: ['SHEET', '#2f7d54'], gslides: ['SLIDES', '#d1852f'], gdraw: ['DRAW', '#7a5ba6'], sheet: ['SHEET', '#2f7d54'], slides: ['SLIDES', '#d1852f'] });\n      const cfCourse = id => CF.courses.find(c => c.id === id) || { id, name: 'Course', color: '#83849a' };\n      const cfColor = c => (/^#[0-9a-f]{3,8}$/i.test(String(c.color || '')) ? c.color : '#83849a');\n      // One status line under the header, for saves and Canva folder changes.\n      let flashState = null;\n      function flash(text, bad, link) {\n        flashState = { text, bad: !!bad, link: link && C() && C().linkOk(link.url) ? link : null };\n        render();\n      }\n      function flashHTML() {\n        if (!flashState) return '';\n        const f = flashState;\n        return `<p class=\"lf-flash${f.bad ? ' bad' : ''}\" role=\"status\">${esc(f.text)}${f.link ? `<a href=\"${esc(f.link.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(f.link.label)}</a>` : ''}<button class=\"lf-flash-x\" type=\"button\" data-flash-close aria-label=\"Dismiss\">×</button></p>`;\n      }\n      const CF_CACHE = 'averages_files_cache';\n      const CF_CACHE_MS = 5 * 60 * 1000;\n      const cfOwner = () => { try { return localStorage.getItem('averages_cloud_owner') || ''; } catch { return ''; } };\n      function cfCached() {\n        try {\n          const c = JSON.parse(sessionStorage.getItem(CF_CACHE) || 'null');\n          if (c && c.owner === cfOwner() && Date.now() - c.at < CF_CACHE_MS && c.data) return c.data;\n        } catch {}\n        return null;\n      }\n      async function loadCourse(fresh) {\n        CF.state = 'loading';\n        render();\n        try {\n          let j = fresh ? null : cfCached();\n          if (!j) {\n            const res = await fetch(`${api}/data/files`, { credentials: 'include' });\n            if (res.status === 401) { window.location.href = '/'; return; }\n            if (!res.ok) throw new Error('status ' + res.status);\n            j = await res.json();\n            if (!j.partial) { try { sessionStorage.setItem(CF_CACHE, JSON.stringify({ at: Date.now(), owner: cfOwner(), data: j })); } catch {} }\n          }\n          CF.courses = (Array.isArray(j.courses) ? j.courses : []).filter(c => c && ID_OK(c.id)).map(c => ({ id: String(c.id), name: String(c.name || 'Course'), color: String(c.color || '') }));\n          CF.classroom = j.platform === 'classroom';\n          CF.files = (Array.isArray(j.files) ? j.files : []).filter(f => f && ID_OK(f.course) && ID_OK(f.parent) && (CF.classroom\n              ? DRIVE_ID_OK(f.id) && DRIVE_URL_OK(f.url) && (f.kind === 'material' || f.kind === 'assignment')\n              : ID_OK(f.id) && (f.kind === 'document' || f.kind === 'assignment')))\n            .map(f => ({ id: String(f.id), name: String(f.name || 'File'), ext: String(f.ext || '').toLowerCase(), course: String(f.course), kind: f.kind, parent: String(f.parent), parentTitle: String(f.parentTitle || ''), at: Number(f.at) || 0, size: Number(f.size) > 0 ? Number(f.size) : 0, url: CF.classroom ? String(f.url) : '' }));\n          CF.partial = !!j.partial;\n          CF.state = 'ready';\n        } catch {\n          CF.state = 'error';\n        }\n        if (LV.filter.startsWith('c:') && !CF.courses.some(c => 'c:' + c.id === LV.filter)) LV.filter = 'all';\n        render();\n      }\n      const cfDownloadUrl = f => `${api}/data/attachment?section=${encodeURIComponent(f.course)}&${f.kind === 'document' ? 'document' : 'assignment'}=${encodeURIComponent(f.parent)}&file=${encodeURIComponent(f.id)}`;\n      function cfSave(app, f) {\n        const K = C();\n        const name = app === 'gdrive' ? 'Google Drive' : 'OneDrive';\n        if (!K) return;\n        let pending;\n        if (app === 'gdrive') {\n          if (!K.googleReady()) { K.prepareGoogle().catch(() => {}); flash(K.messageFor('not_ready'), true); return; }\n          pending = K.googleSession({ interactive: true });   // inside the click: may open Google's window\n        } else {\n          pending = K.oneDriveToken({ interactive: true });\n        }\n        flash(`Saving \"${f.name}\" to ${name}…`);\n        const src = { section: f.course, fileId: f.id, name: f.name };\n        if (f.kind === 'document') src.document = f.parent; else src.assignment = f.parent;\n        pending\n          .then(async token => {\n            const blob = await K.fetchAttachment(src);\n            return app === 'gdrive' ? K.googleUpload(token, { name: f.name, blob }) : K.oneDriveUpload(token, { name: f.name, blob });\n          })\n          .then(saved => {\n            flash(`Saved \"${saved.name || f.name}\" to ${app === 'gdrive' ? 'the Averages.io folder in your Google Drive' : 'Apps/Averages.io in your OneDrive'}.`, false, { url: saved.webViewLink || saved.webUrl, label: `Open in ${name}` });\n            if (cfg) startCloud(app);   // the new file shows up in the list too\n          })\n          .catch(err => flash(K.messageFor(err), !err || err.code !== 'popup_closed'));\n      }\n\n      // ---------- Attach to an assignment (2026-10-06) ----------\n      // Opens the assignment with the file already in Add Submission\n      // (/assignment reads ?attach=). Assignments only (tests are taken on\n      // Schoology, discussions are posts): the open ones and the overdue ones,\n      // from the bundle's UPCOMING and OVERDUE, the latest due date first.\n      // Google Classroom work is turned in on Classroom, so Classroom students\n      // don't get Attach.\n      const LIVE_DATA = (window.__AVERAGES__ && window.__AVERAGES__.data) || {};\n      function isClassroom() { return LIVE_DATA.platform === 'classroom' || !!CF.classroom; }\n      const DUE_MONTH = /\\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\\.?\\s+(\\d{1,2})\\b/i;\n      const MONTH_N = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };\n      // \"Fri Oct 9\" has no year: open work is due ahead of today, overdue work behind it.\n      function dueAt(x, overdue) {\n        const exact = Date.parse(String(x.dueAt || ''));\n        if (exact) return exact;\n        const m = String(x.due || '').match(DUE_MONTH);\n        if (!m) return -Infinity;   // no due date: last\n        const now = new Date();\n        const d = new Date(now.getFullYear(), MONTH_N[m[1].toLowerCase()], Number(m[2]));\n        if (overdue && d - now > 2 * DAY) d.setFullYear(d.getFullYear() - 1);\n        if (!overdue && now - d > 2 * DAY) d.setFullYear(d.getFullYear() + 1);\n        return d.getTime();\n      }\n      function attachTargets(courseId) {\n        const out = [];\n        const seen = new Set();\n        const add = (list, overdue) => (Array.isArray(list) ? list : []).forEach(x => {\n          if (!x || !ID_OK(x.id) || !ID_OK(x.courseId) || (x.type && x.type !== 'assignment')) return;\n          if (courseId && String(x.courseId) !== courseId) return;\n          const key = `${x.courseId}:${x.id}`;\n          if (seen.has(key)) return;\n          seen.add(key);\n          out.push({ id: String(x.id), course: String(x.courseId), title: String(x.title || 'Assignment'), due: String(x.due || ''), overdue, at: dueAt(x, overdue) });\n        });\n        add(LIVE_DATA.UPCOMING, false);\n        add(LIVE_DATA.OVERDUE, true);\n        return out.sort((a, b) => (a.at === b.at ? a.title.localeCompare(b.title) : b.at > a.at ? 1 : -1));\n      }\n      function attachCourse(id) {\n        const c = (Array.isArray(LIVE_DATA.COURSES) ? LIVE_DATA.COURSES : []).find(x => x && String(x.id) === id) || CF.courses.find(x => x.id === id) || {};\n        return { name: String(c.name || 'Class'), color: cfColor(c) };\n      }\n      function attachTo(file, t) {\n        window.location.href = avgAssignHref(t.course, t.title, t.id, `&attach=${encodeURIComponent(JSON.stringify(file))}`);\n      }\n      // A second menu in the same spot: one class's assignments (a course\n      // file), or every class's, grouped by class (Drive, OneDrive, Canva).\n      function openAttach(file, courseId) {\n        const targets = attachTargets(courseId);\n        const row = t => ({ label: t.title, sub: t.overdue ? `Late${t.due ? ' · was due ' + t.due : ''}` : (t.due ? `Due ${t.due}` : 'No due date'), run: () => attachTo(file, t) });\n        let list;\n        if (courseId) list = targets.map(row);\n        else {\n          const order = (Array.isArray(LIVE_DATA.COURSES) ? LIVE_DATA.COURSES : []).map(c => String(c && c.id));\n          const rank = id => (order.indexOf(id) === -1 ? 1e9 : order.indexOf(id));\n          list = [];\n          [...new Set(targets.map(t => t.course))].sort((a, b) => rank(a) - rank(b)).forEach(id => {\n            const c = attachCourse(id);\n            list.push({ group: c.name, color: c.color });\n            targets.filter(t => t.course === id).forEach(t => list.push(row(t)));\n          });\n        }\n        if (!list.length) list = [{ note: courseId ? 'No assignments to turn in for this class right now.' : 'No assignments to turn in right now.' }];\n        if (fxLast) openFxMenu(fxLast.anchor, `Attach \"${file.name}\" to`, list, { x: fxLast.x, y: fxLast.y });\n      }\n\n      // ---------- Canva ----------\n      // Designs: GET /canva/designs (newest first). Folders (when switched\n      // on): GET /canva/folders/:id/items, one folder at a time.\n      const CV = { state: 'loading', items: [], next: null, folders: 'off', busy: false };\n      // Canva's thumbnail links come from Canva's own CDN and expire; only https ones are used.\n      const thumbOk = u => /^https:\\/\\//i.test(String(u || ''));\n      async function loadCanva(more) {\n        if (!more) { CV.state = 'loading'; render(); }\n        try {\n          const res = await fetch(`${api}/canva/designs${more && CV.next ? '?continuation=' + encodeURIComponent(CV.next) : ''}`, { credentials: 'include' });\n          if (res.status === 401) { window.location.href = '/'; return; }\n          if (res.status === 503) { CV.state = 'soon'; render(); return; }\n          const j = await res.json();\n          if (j.connected === false) { CV.state = 'connect'; CV.items = []; render(); return; }\n          if (!res.ok) throw new Error(j.error || 'status ' + res.status);\n          const got = (Array.isArray(j.items) ? j.items : []).filter(d => d && /^[A-Za-z0-9_-]{1,64}$/.test(String(d.id)));\n          CV.items = more ? CV.items.concat(got) : got;\n          CV.next = typeof j.continuation === 'string' ? j.continuation : null;\n          CV.state = 'ready';\n        } catch {\n          CV.state = 'error';\n        }\n        render();\n      }\n      async function loadCanvaStatus() {\n        try {\n          const res = await fetch(`${api}/canva/status`, { credentials: 'include' });\n          const j = await res.json();\n          CV.folders = j && (j.folders === 'ready' || j.folders === 'reconnect') ? j.folders : 'off';\n        } catch {\n          CV.folders = 'off';\n        }\n        render();\n      }\n\n      // ---- Canva opens in a new tab (2026-10-07, Martin) ----\n      // The tab is opened on the click itself (a tab opened after waiting for\n      // our API would be blocked as a pop-up), shows \"Opening Canva…\", and is\n      // sent to Canva once the API answers. Blocked anyway: this tab goes.\n      function openCanvaTab() {\n        let tab = null;\n        try { tab = window.open('', '_blank'); } catch {}\n        if (!tab) return null;\n        try {\n          tab.opener = null;\n          tab.document.title = 'Opening Canva…';\n          tab.document.body.style.cssText = 'margin:0;display:grid;place-items:center;height:100vh;font:600 16px -apple-system,system-ui,sans-serif;color:#555;background:#f4f4f6';\n          tab.document.body.textContent = 'Opening Canva…';\n        } catch {}\n        return tab;\n      }\n      /** Sends the tab to Canva; true when it went there (this page stays). */\n      function sendToCanva(tab, url) {\n        if (tab && !tab.closed) { try { tab.location.replace(url); return true; } catch {} }\n        window.location.assign(url);\n        return false;\n      }\n      function closeCanvaTab(tab) { try { if (tab && !tab.closed) tab.close(); } catch {} }\n      async function openDesign(id, el) {\n        if (!id || (el && el.getAttribute('aria-busy') === 'true')) return;\n        if (el) el.setAttribute('aria-busy', 'true');\n        const tab = openCanvaTab();\n        try {\n          const res = await fetch(`${api}/canva/designs/${encodeURIComponent(id)}/open`, {\n            method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ returnTo: '/files' }),\n          });\n          const j = await res.json().catch(() => ({}));\n          if (res.ok && CANVA_EDIT_URL.test(String(j.editUrl || ''))) { sendToCanva(tab, j.editUrl); return; }\n          closeCanvaTab(tab);\n          if (j.error === 'canva_design_gone') {\n            CV.items = CV.items.filter(x => x.id !== id);\n            FD.items = FD.items.filter(x => x.id !== id);\n            flash('That design isn’t in your Canva anymore.', true);\n            return;\n          }\n          if (j.error === 'canva_not_connected' || j.error === 'canva_reconnect_needed') { loadCanva(false); return; }\n          flash('Couldn’t open that design in Canva. Try again in a moment.', true);\n        } catch {\n          closeCanvaTab(tab);\n          flash('Couldn’t open that design in Canva. Try again in a moment.', true);\n        } finally {\n          if (el && el.isConnected) el.removeAttribute('aria-busy');\n        }\n      }\n\n      // ---------- Canva folders (2026-10-06) ----------\n      // path: where the student is, from the top of their Canva Projects.\n      const FD = { path: [{ id: 'root', name: 'Projects' }], items: [], next: null, state: 'idle', form: null, formBusy: false };\n      const FOLDER_ERR = {\n        canva_item_in_multiple_folders: 'That design is in more than one folder, so Canva only lets you move it in Canva itself.',\n        canva_folder_full: 'That folder is full in Canva.',\n        canva_folder_gone: 'That folder isn’t in your Canva anymore.',\n        canva_folder_not_allowed: 'Canva doesn’t let you change that one.',\n        canva_rate_limited: 'Canva is busy. Try again in a minute.',\n        canva_reconnect_needed: 'Reconnect Canva in Settings to use your folders.',\n      };\n      const folderErr = code => FOLDER_ERR[code] || 'Something went wrong in Canva. Try again in a moment.';\n      const hereId = () => FD.path[FD.path.length - 1].id;\n      async function loadFolder(more) {\n        if (!more) { FD.state = 'loading'; FD.items = []; FD.next = null; render(); }\n        const id = hereId();\n        try {\n          const q = more && FD.next ? '?continuation=' + encodeURIComponent(FD.next) : '';\n          const res = await fetch(`${api}/canva/folders/${encodeURIComponent(id)}/items${q}`, { credentials: 'include' });\n          if (res.status === 401) { window.location.href = '/'; return; }\n          const j = await res.json().catch(() => ({}));\n          if (id !== hereId()) return;   // moved on while it loaded\n          if (j.connected === false) { CV.state = 'connect'; FD.state = 'idle'; render(); return; }\n          if (j.error === 'canva_reconnect_needed') { CV.folders = 'reconnect'; FD.state = 'idle'; render(); return; }\n          if (j.error === 'canva_folder_gone' && FD.path.length > 1) { FD.path.pop(); flash(folderErr(j.error), true); loadFolder(false); return; }\n          if (!res.ok) throw new Error(j.error || 'status');\n          const got = (Array.isArray(j.items) ? j.items : []).filter(x => x && (x.type === 'folder' || x.type === 'design') && /^[A-Za-z0-9_-]{1,50}$/.test(String(x.id)));\n          FD.items = more ? FD.items.concat(got) : got;\n          FD.next = typeof j.continuation === 'string' ? j.continuation : null;\n          FD.state = 'ready';\n        } catch {\n          if (id === hereId()) FD.state = 'error';\n        }\n        render();\n      }\n      function goFolder(index, folder) {\n        if (folder) FD.path.push({ id: folder.id, name: folder.name || 'Untitled folder' });\n        else FD.path = FD.path.slice(0, index + 1);\n        FD.form = null;\n        loadFolder(false);\n      }\n      async function folderPost(path, body) {\n        const res = await fetch(`${api}${path}`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });\n        const j = await res.json().catch(() => ({}));\n        if (!res.ok) throw Object.assign(new Error(j.error || 'failed'), { code: j.error || '' });\n        return j;\n      }\n      async function submitFolderForm(name) {\n        const form = FD.form;\n        if (!form || FD.formBusy) return;\n        const clean = String(name || '').replace(/\\s+/g, ' ').trim();\n        if (!clean) return;\n        FD.formBusy = true;\n        render();\n        try {\n          if (form.mode === 'new') {\n            const j = await folderPost('/canva/folders', { name: clean, parentId: hereId() });\n            FD.form = null;\n            flash(`Made the folder \"${(j.folder && j.folder.name) || clean}\".`);\n          } else {\n            const j = await folderPost(`/canva/folders/${encodeURIComponent(form.id)}/rename`, { name: clean });\n            FD.form = null;\n            flash(`Renamed it to \"${(j.folder && j.folder.name) || clean}\".`);\n          }\n          loadFolder(false);\n        } catch (err) {\n          flash(folderErr(err.code), true);\n        } finally {\n          FD.formBusy = false;\n          render();\n        }\n      }\n      async function moveTo(item, to) {\n        try {\n          await folderPost('/canva/folders/move', { itemId: item.id, toFolderId: to.id });\n          flash(`Moved \"${item.name}\" to ${to.name}.`);\n          FD.items = FD.items.filter(x => x.id !== item.id);\n          render();\n        } catch (err) {\n          flash(folderErr(err.code), true);\n        }\n      }\n      /** Where a design can go from here: up a level, the top, or a folder next to it. */\n      function openMoveMenu(item) {\n        const list = [];\n        const seen = new Set([hereId(), item.id]);\n        const add = (f, sub) => { if (seen.has(f.id)) return; seen.add(f.id); list.push({ label: f.name, sub, run: () => moveTo(item, f) }); };\n        if (FD.path.length > 1) {\n          add(FD.path[FD.path.length - 2], 'Up one level');\n          add(FD.path[0], 'Top of your Canva Projects');\n        }\n        FD.items.filter(x => x.type === 'folder').forEach(f => add({ id: f.id, name: f.name || 'Untitled folder' }, 'In this folder'));\n        if (!list.length) list.push({ note: 'Make a folder here first, then move it in.' });\n        if (fxLast) openFxMenu(fxLast.anchor, `Move \"${item.name}\" to`, list, { x: fxLast.x, y: fxLast.y });\n      }\n      const foldersOn = () => CV.state === 'ready' && CV.folders === 'ready';\n\n      // ---------- One list: every source as entries ----------\n      function sourceState(src) {\n        if (src === 'course') return CF.state;\n        if (src === 'canva') return CV.state;\n        return CLOUD[src].state;\n      }\n      // Only the sources a student has (Martin, 10-6: \"if a source is not\n      // connected can you remove it\"): one that isn't connected, or isn't\n      // switched on yet, leaves the sidebar. Add files connects them.\n      const HIDDEN_STATES = ['connect', 'soon', 'off'];\n      function srcList() {\n        if (INCOGNITO) return ['course'];\n        return ['course', 'gdrive', 'onedrive', 'canva'].filter(src => src === 'course' || !HIDDEN_STATES.includes(sourceState(src)));\n      }\n      function entries() {\n        const out = [];\n        if (CF.state === 'ready') CF.files.forEach((f, i) => {\n          const c = cfCourse(f.course);\n          out.push({ key: 'cf:' + i, src: 'course', name: f.name, ext: f.ext, t: f.at, course: f.course,\n            from: `${c.name} · ${f.kind === 'assignment' ? f.parentTitle : 'Materials'}`, color: cfColor(c), size: f.size, raw: f });\n        });\n        if (!INCOGNITO) {\n          ['gdrive', 'onedrive'].forEach(app => {\n            if (CLOUD[app].state !== 'ready') return;\n            CLOUD[app].files.forEach((f, i) => out.push({ key: `${app}:${i}`, src: app, name: f.name, ext: f.type, kind: f.kind, t: f.t, from: app === 'gdrive' ? `Google Drive · ${f.kind}` : 'OneDrive', size: f.size, thumb: f.thumb || '', raw: f }));\n          });\n          if (CV.state === 'ready') CV.items.forEach(d => out.push({ key: 'cv:' + d.id, src: 'canva', name: String(d.title || 'Untitled design'), ext: 'canva', t: Number(d.updatedAt) || 0, from: 'Canva', thumb: d.thumbnailUrl, raw: d }));\n        }\n        return out;\n      }\n      const isRecent = e => e.t > 0 && Date.now() - e.t <= RECENT_DAYS * DAY;\n      function inFilterLive(e, filter) {\n        if (filter === 'all') return true;\n        if (filter === 'recent') return isRecent(e);\n        if (filter.startsWith('c:')) return e.src === 'course' && e.course === filter.slice(2);\n        return e.src === filter;\n      }\n      const matchesLive = e => !LV.query || `${e.name} ${e.from}`.toLowerCase().includes(LV.query);\n      const newest = (a, b) => (b.t - a.t) || a.name.localeCompare(b.name);\n      const LIVE_SRC_NAME = { course: 'Course Files', gdrive: 'Google Drive', onedrive: 'OneDrive', canva: 'Canva' };\n      function titleLive() {\n        if (LV.filter === 'all') return 'All Files';\n        if (LV.filter === 'recent') return 'Recents';\n        if (LV.filter.startsWith('c:')) return cfCourse(LV.filter.slice(2)).name;\n        return LIVE_SRC_NAME[LV.filter] || 'Files';\n      }\n\n      // ---------- Drawing ----------\n      // Google's own files (Docs, Sheets, Slides) get Google's icons, not Word's or Excel's.\n      const iconKey = e => (e.src === 'canva' ? 'canva' : (e.src === 'gdrive' && ({ Docs: 'gdoc', Sheets: 'gsheet', Slides: 'gslide' })[e.kind]) || e.ext);\n      function badgeLive(e) {\n        if (e.folder) return `<span class=\"fx-badge lf-folder-badge\" aria-hidden=\"true\">${FOLDER_ICON}</span>`;\n        if (AVFI()) return AVFI().html(iconKey(e), { size: 34 });\n        if (e.src === 'canva') return '<span class=\"fx-badge canva\" aria-hidden=\"true\"><span class=\"cm\"></span></span>';\n        const b = (Object.prototype.hasOwnProperty.call(CF_BADGE, e.ext) && CF_BADGE[e.ext]) || (Object.prototype.hasOwnProperty.call(BADGE, e.ext) && BADGE[e.ext]) || [String(e.ext || 'file').toUpperCase().slice(0, 4), '#83849a'];\n        return `<span class=\"fx-badge\" aria-hidden=\"true\" style=\"background:${esc(b[1])}\">${esc(b[0])}</span>`;\n      }\n      function fromLive(e) {\n        if (e.src === 'course') return `<span class=\"fx-dot\" style=\"background:${esc(e.color)}\"></span><span class=\"lf-ell\">${esc(e.from)}</span>`;\n        return `<span class=\"lf-ell\">${esc(e.from)}</span>`;\n      }\n      function thumbLive(e) {\n        if (e.folder) return `<span class=\"fx-thumb lf-folder-thumb\">${FOLDER_ICON}</span>`;\n        if (e.src === 'canva') {\n          return thumbOk(e.thumb)\n            ? `<span class=\"fx-thumb canva\"><img src=\"${esc(e.thumb)}\" alt=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer\"></span>`\n            : '<span class=\"fx-thumb canva\" style=\"background:linear-gradient(135deg,#7d2ae7,#00c4cc)\"><span class=\"page\"><i></i><i></i><i></i></span></span>';\n        }\n        const plain = AVFI() ? `<span class=\"fx-thumb avfi-thumb\" style=\"background:${AVFI().color(iconKey(e))}14\">${AVFI().html(iconKey(e), { size: 64 })}</span>`\n          : `<span class=\"fx-thumb\" style=\"background:${THUMB[e.ext] || '#e4e4e8'}\"><span class=\"page\"><i></i><i></i><i></i><i></i><i></i></span></span>`;\n        // Google Drive previews (2026-10-07): Google's image, or the plain page if it won't load.\n        if (e.src === 'gdrive' && GDRIVE_THUMB_OK(e.thumb)) {\n          return `<span class=\"fx-thumb lf-gthumb\" style=\"background:${THUMB[e.ext] || '#e4e4e8'}\"><img src=\"${esc(e.thumb)}\" alt=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer\" data-thumb-fallback></span>`;\n        }\n        return plain;\n      }\n      // Only Google's own image host, over https.\n      const GDRIVE_THUMB_OK = u => /^https:\\/\\/[a-z0-9-]+\\.googleusercontent\\.com\\//i.test(String(u || ''));\n      // A preview that won't load (they expire after a few hours) becomes the plain page.\n      document.addEventListener('error', ev => {\n        const img = ev.target;\n        if (!img || img.tagName !== 'IMG' || !img.hasAttribute('data-thumb-fallback')) return;\n        const box = img.parentElement;\n        img.remove();\n        if (box) box.insertAdjacentHTML('beforeend', '<span class=\"page\"><i></i><i></i><i></i><i></i><i></i></span>');\n      }, true);\n      const moreBtn = e => `<button class=\"fx-more\" type=\"button\" data-lv-more=\"${esc(e.key)}\" aria-label=\"More for ${esc(e.name)}\" aria-haspopup=\"menu\" aria-expanded=\"false\">${MORE_ICON}</button>`;\n      function rowLive(e) {\n        const when = dayLabel(e.t);\n        return `<div class=\"fx-row\" role=\"row\" tabindex=\"0\" data-lv=\"${esc(e.key)}\" aria-label=\"${esc(e.name)}, ${esc(e.from)}${when ? ', changed ' + esc(when) : ''}\">\n            ${badgeLive(e)}\n            <span class=\"fx-name\"><span>${esc(e.name)}</span><small>${esc(e.from)}${when ? ' · ' + esc(when) : ''}</small></span>\n            <span class=\"fx-src\">${fromLive(e)}</span>\n            <span class=\"fx-date\">${esc(when)}</span>\n            ${moreBtn(e)}\n          </div>`;\n      }\n      function tileLive(e) {\n        const when = dayLabel(e.t);\n        const sub = e.folder ? 'Folder' : e.src === 'course' ? fromLive(e) : esc(e.from);\n        return `<div class=\"lf-tile\"><button class=\"fx-tile\" type=\"button\" data-lv=\"${esc(e.key)}\" aria-label=\"${esc(e.name)}, ${esc(e.folder ? 'folder' : e.from)}\">${thumbLive(e)}<span class=\"fx-tile-name\">${esc(e.name)}</span><span class=\"fx-tile-src\">${sub}${when ? ' · ' + esc(when) : ''}</span></button>${moreBtn(e).replace('class=\"fx-more\"', 'class=\"fx-more lf-tile-more\"')}</div>`;\n      }\n      function listHTML(list, label) {\n        return fxView === 'grid'\n          ? `<div class=\"fx-grid\">${list.map(tileLive).join('')}</div>`\n          : `<div class=\"fx-list\" role=\"table\" aria-label=\"${esc(label)}\"><div class=\"fx-row head\" role=\"row\"><span></span><span>Name</span><span>From</span><span>Changed</span><span></span></div>${list.map(rowLive).join('')}</div>`;\n      }\n\n      // What a source says when it isn't showing files (connect, loading, errors).\n      function sourcePanel(src) {\n        const st = sourceState(src);\n        if (src === 'course') {\n          if (st === 'loading') return '<div class=\"fx-empty\"><strong>Loading your course files…</strong>This takes a moment the first time: every class is asked for its files.</div>';\n          if (st === 'error') return '<div class=\"fx-empty\"><strong>Couldn’t load your course files</strong>Try again in a moment.<br><button class=\"fx-more-designs\" type=\"button\" data-cf-retry>Try again</button></div>';\n          return '';\n        }\n        if (src === 'canva') {\n          if (st === 'loading') return '<div class=\"fx-empty\"><strong>Loading your Canva designs…</strong></div>';\n          if (st === 'soon') return '<div class=\"fx-empty\"><strong>Canva is coming soon</strong>Designs you edit in Canva from Averages.io will show up here.</div>';\n          if (st === 'connect') return '<div class=\"fx-empty\"><strong>Connect Canva to see your designs here</strong>Averages.io shows your Canva designs and opens them in Canva.<br><button class=\"fx-connect\" type=\"button\" data-connect-canva>Connect Canva</button></div>';\n          if (st === 'error') return '<div class=\"fx-empty\"><strong>Couldn’t load your Canva designs</strong>Try again in a moment.<br><button class=\"fx-more-designs\" type=\"button\" data-retry-designs>Try again</button></div>';\n          return '';\n        }\n        const c = CLOUD[src];\n        const acct = C() ? C().accounts()[src] : null;\n        if (st === 'loading') return `<div class=\"fx-empty\"><strong>Loading your ${esc(c.name)} files…</strong></div>`;\n        if (st === 'soon') return `<div class=\"fx-empty\"><strong>${esc(c.name)} is coming soon</strong>Files you save to ${esc(c.name)} with Averages.io will show up here.</div>`;\n        if (st === 'error') return `<div class=\"fx-empty\"><strong>Couldn’t load your ${esc(c.name)} files</strong>${esc(c.message || 'Try again in a moment.')}<br><button class=\"fx-more-designs\" type=\"button\" data-cloud-retry=\"${src}\">Try again</button></div>`;\n        if (st === 'connect') return `<div class=\"fx-empty\"><strong>Connect ${esc(c.name)} to see your files here</strong>${src === 'onedrive' ? 'Averages.io saves into its own Apps/Averages.io folder. Add from OneDrive asks to read your files, and only the ones you pick show up here.' : 'Averages.io only sees the files it saves there or that you add, never the rest of your drive.'}<br><button class=\"fx-connect\" type=\"button\" data-cloud-connect=\"${src}\"${c.busy ? ' disabled' : ''}>Connect ${esc(c.name)}</button></div>`;\n        if (st === 'click') return `<div class=\"fx-empty\"><strong>Your ${esc(c.name)} files</strong>${acct && (acct.email || acct.username) ? 'Connected as ' + esc(acct.email || acct.username) + '. ' : ''}${esc(c.name)} may ask you to confirm it’s you.<br><button class=\"fx-connect\" type=\"button\" data-cloud-show=\"${src}\"${c.busy ? ' disabled' : ''}>Show files</button></div>`;\n        return '';\n      }\n      // A drive that needs its sign-in again (Martin, 10-6): one banner each,\n      // on every view except that drive's own (its panel already asks).\n      // Its x hides it for the rest of this tab's visit (Martin, 10-6).\n      const REAUTH_KEY = 'averages_files_reauth_hidden';\n      const reauthHidden = new Set((() => { try { const v = JSON.parse(sessionStorage.getItem(REAUTH_KEY) || '[]'); return Array.isArray(v) ? v : []; } catch { return []; } })());\n      function hideReauth(app) {\n        reauthHidden.add(app);\n        try { sessionStorage.setItem(REAUTH_KEY, JSON.stringify([...reauthHidden])); } catch {}\n        render();\n      }\n      function reauthHTML() {\n        if (INCOGNITO) return '';\n        return ['gdrive', 'onedrive'].filter(app => CLOUD[app].state === 'click' && LV.filter !== app && !reauthHidden.has(app)).map(app => {\n          const c = CLOUD[app];\n          return `<div class=\"lf-reauth\" role=\"status\"><span><b>${esc(c.name)}</b> needs you to sign in again to show your files.</span><button type=\"button\" data-cloud-show=\"${app}\"${c.busy ? ' disabled' : ''}>Sign in to ${esc(c.name)}</button><button class=\"lf-reauth-x\" type=\"button\" data-reauth-hide=\"${app}\" aria-label=\"Hide this ${esc(c.name)} message\">×</button></div>`;\n        }).join('');\n      }\n      function navLive(all) {\n        const count = filter => {\n          if (['course', 'gdrive', 'onedrive', 'canva'].includes(filter)) {\n            const st = sourceState(filter);\n            if (st === 'loading') return '…';\n            if (st !== 'ready') return '';\n          }\n          return String(all.filter(e => inFilterLive(e, filter)).length);\n        };\n        const item = (filter, label, extra) => `<button class=\"fx-item${LV.filter === filter ? ' on' : ''}\" type=\"button\" data-filter=\"${esc(filter)}\" aria-current=\"${LV.filter === filter ? 'true' : 'false'}\">${extra || ''}<span class=\"nm\">${esc(label)}</span><span class=\"n\">${esc(count(filter))}</span></button>`;\n        const withFiles = CF.courses.filter(c => CF.files.some(f => f.course === c.id));\n        document.getElementById('fxNav').innerHTML =\n          item('all', 'All Files') + item('recent', 'Recents') +\n          '<p class=\"fx-label\">Sources</p>' + srcList().map(src => item(src, LIVE_SRC_NAME[src])).join('') +\n          (withFiles.length ? '<p class=\"fx-label\">Courses</p>' + withFiles.map(c => item('c:' + c.id, c.name, `<span class=\"fx-dot\" style=\"background:${esc(cfColor(c))}\"></span>`)).join('') : '');\n      }\n      function toolsLive() {\n        const seg = `<div class=\"fx-seg\" role=\"group\" aria-label=\"View\"><button type=\"button\" data-view=\"list\" aria-pressed=\"${fxView === 'list'}\">List</button><button type=\"button\" data-view=\"grid\" aria-pressed=\"${fxView === 'grid'}\">Grid</button></div>`;\n        let extra = '';\n        const f = LV.filter;\n        if (f === 'course' || f.startsWith('c:')) extra = '<button class=\"fx-add\" type=\"button\" data-cf-refresh>Refresh</button>';\n        else if (f === 'gdrive' || f === 'onedrive') {\n          const st = CLOUD[f].state;\n          if ((st === 'ready' || st === 'click') && canPick(f)) extra = `<button class=\"fx-add\" type=\"button\" ${f === 'gdrive' ? 'data-pick-drive' : 'data-pick-onedrive'}${CLOUD[f].busy ? ' disabled' : ''}>${PLUS_ICON}Add from ${esc(CLOUD[f].name)}</button>`;\n        } else if (f === 'canva') {\n          if (foldersOn()) extra = `<button class=\"fx-add\" type=\"button\" data-folder-new${FD.formBusy ? ' disabled' : ''}>${PLUS_ICON}New folder</button>`;\n        } else if (!INCOGNITO) extra = `<button class=\"fx-add\" type=\"button\" data-lv-add aria-haspopup=\"menu\" aria-expanded=\"false\">${PLUS_ICON}Add files</button>`;\n        return seg + extra;\n      }\n      function chipsLive() {\n        return [['all', 'All'], ['recent', 'Recents']].concat(srcList().map(s => [s, s === 'course' ? 'Courses' : LIVE_SRC_NAME[s]]))\n          .map(([k, l]) => `<button class=\"fx-chip\" type=\"button\" data-filter=\"${k}\" aria-pressed=\"${LV.filter === k}\">${l}</button>`).join('');\n      }\n      function folderBrowserHTML() {\n        const crumbs = FD.path.map((p, i) => i === FD.path.length - 1\n          ? `<span aria-current=\"location\">${esc(p.name)}</span>`\n          : `<button type=\"button\" data-crumb=\"${i}\">${esc(p.name)}</button>`).join('<span class=\"sep\" aria-hidden=\"true\">›</span>');\n        let body = `<nav class=\"lf-crumbs\" aria-label=\"Canva folders\"><span class=\"cm\" aria-hidden=\"true\"></span>${crumbs}</nav>`;\n        if (FD.form) {\n          body += `<form class=\"lf-form\" data-folder-form><label class=\"sr-only\" for=\"lfFolderName\">${FD.form.mode === 'new' ? 'New folder name' : 'Folder name'}</label>\n              <input id=\"lfFolderName\" type=\"text\" maxlength=\"255\" autocomplete=\"off\" value=\"${esc(FD.form.value || '')}\" placeholder=\"${FD.form.mode === 'new' ? 'New folder name' : 'Folder name'}\"${FD.formBusy ? ' disabled' : ''}>\n              <button class=\"fx-connect\" type=\"submit\"${FD.formBusy ? ' disabled' : ''}>${FD.form.mode === 'new' ? 'Make folder' : 'Rename'}</button>\n              <button class=\"fx-add\" type=\"button\" data-folder-cancel${FD.formBusy ? ' disabled' : ''}>Cancel</button></form>`;\n        }\n        if (FD.state === 'loading' || FD.state === 'idle') return body + '<div class=\"fx-empty\"><strong>Loading your Canva folders…</strong></div>';\n        if (FD.state === 'error') return body + '<div class=\"fx-empty\"><strong>Couldn’t load this folder</strong>Try again in a moment.<br><button class=\"fx-more-designs\" type=\"button\" data-folder-retry>Try again</button></div>';\n        const list = FD.items.map(x => ({ key: (x.type === 'folder' ? 'fd:' : 'fv:') + x.id, src: 'canva', folder: x.type === 'folder', name: String(x.name || (x.type === 'folder' ? 'Untitled folder' : 'Untitled design')), ext: 'canva', t: Number(x.updatedAt) || 0, from: x.type === 'folder' ? 'Folder' : 'Canva', thumb: x.thumbnailUrl, raw: x }))\n          .filter(matchesLive)\n          .sort((a, b) => (b.folder - a.folder) || newest(a, b));\n        if (!list.length) return body + `<div class=\"fx-empty\"><strong>${LV.query ? 'Nothing here' : 'This folder is empty'}</strong>${LV.query ? `No designs or folders match \"${esc(LV.query)}\".` : 'Make a folder with New folder, or move designs here from their ⋯ menu.'}</div>`;\n        return body + listHTML(list, FD.path[FD.path.length - 1].name) + (FD.next ? '<button class=\"fx-more-designs\" type=\"button\" data-folder-more>Show more</button>' : '');\n      }\n      // Entries on screen right now, by key, for clicks and menus.\n      let shownByKey = new Map();\n      function render() {\n        if (!main.isConnected) return;\n        if (['gdrive', 'onedrive', 'canva'].includes(LV.filter) && !srcList().includes(LV.filter)) LV.filter = 'all';\n        const all = entries();\n        navLive(all);\n        const canvaFolders = LV.filter === 'canva' && foldersOn();\n        const list = all.filter(e => inFilterLive(e, LV.filter) && matchesLive(e)).sort(newest);\n        shownByKey = new Map();\n        let body = flashHTML() + reauthHTML();\n        let count = `${list.length} file${list.length === 1 ? '' : 's'}`;\n        if (canvaFolders) {\n          if (FD.state === 'idle') { FD.state = 'loading'; queueMicrotask(() => loadFolder(false)); }\n          body += folderBrowserHTML();\n          FD.items.forEach(x => shownByKey.set((x.type === 'folder' ? 'fd:' : 'fv:') + x.id, { key: (x.type === 'folder' ? 'fd:' : 'fv:') + x.id, src: 'canva', folder: x.type === 'folder', name: String(x.name || (x.type === 'folder' ? 'Untitled folder' : 'Untitled design')), raw: x }));\n          const n = FD.items.length;\n          count = FD.state === 'ready' ? `${n} item${n === 1 ? '' : 's'}${FD.next ? '+' : ''}` : '';\n        } else {\n          const single = ['course', 'gdrive', 'onedrive', 'canva'].includes(LV.filter) ? LV.filter : (LV.filter.startsWith('c:') ? 'course' : null);\n          const panel = single ? sourcePanel(single) : '';\n          if (panel) {\n            body += panel;\n            count = '';\n          } else {\n            if (LV.filter === 'canva' && CV.folders === 'reconnect') body += '<div class=\"lf-states\" role=\"status\"><span class=\"lf-state\"><b>Canva folders</b> Reconnect Canva to see your folders here.<button type=\"button\" data-connect-canva>Reconnect</button></span></div>';\n            const showRecent = LV.filter === 'all' && !LV.query && fxView === 'list' && list.length > 4;\n            if (!list.length) {\n              const loading = (single ? [single] : srcList()).some(s => sourceState(s) === 'loading');\n              body += loading ? '' : `<div class=\"fx-empty\"><strong>Nothing here</strong>${LV.query ? `No files match \"${esc(LV.query)}\".` : LV.filter === 'recent' ? `Nothing changed in the last ${RECENT_DAYS} days.` : 'No files yet.'}</div>`;\n            } else {\n              if (showRecent) body += `<p class=\"fx-sec\">Recent</p><div class=\"fx-grid\">${list.slice(0, 4).map(tileLive).join('')}</div>`;\n              const shown = list.slice(0, LV.shown);\n              body += `<p class=\"fx-sec\">${showRecent ? 'All files' : (LV.query ? 'Results' : 'Files')}</p>` + listHTML(shown, titleLive());\n              if (list.length > shown.length) body += `<button class=\"fx-more-designs\" type=\"button\" data-lv-showmore>Show more (${list.length - shown.length})</button>`;\n            }\n            if (LV.filter === 'canva' && CV.next) body += '<button class=\"fx-more-designs\" type=\"button\" data-more-designs>Load more Canva designs</button>';\n            list.forEach(e => shownByKey.set(e.key, e));\n          }\n          if ((LV.filter === 'course' || LV.filter.startsWith('c:') || LV.filter === 'all') && CF.partial) body += '<p class=\"fx-note\">Some classes didn’t answer, so a few course files may be missing. Use Refresh under Course Files to try again.</p>';\n          if (!INCOGNITO && (LV.filter === 'all' || LV.filter === 'recent' || LV.filter === 'gdrive' || LV.filter === 'onedrive')) body += '<p class=\"fx-note\">Google Drive and OneDrive show the files you save, edit or add with Averages.io, not your whole drive.</p>';\n          if (INCOGNITO && (LV.filter === 'all' || LV.filter === 'recent')) body += '<p class=\"fx-note\">Google Drive, OneDrive and Canva are off in Incognito mode: it stores nothing about you on our servers.</p>';\n        }\n        const focusId = document.activeElement && document.activeElement.id === 'lfFolderName' ? 'lfFolderName' : null;\n        main.innerHTML = `\n          <div class=\"fx-head\">\n            <h2>${esc(titleLive())}</h2>${count ? `<span class=\"fx-meta\">${esc(count)}</span>` : ''}\n            <div class=\"fx-tools\">${toolsLive()}</div>\n          </div>\n          <div class=\"fx-chips\" role=\"group\" aria-label=\"Show files from\">${chipsLive()}</div>\n          ${body}`;\n        const total = all.length;\n        const bytes = all.reduce((n, e) => n + (Number(e.size) || 0), 0);\n        document.getElementById('filesSub').textContent = `${total} file${total === 1 ? '' : 's'} · ${sizeLabel(bytes)}`;\n        const input = document.getElementById('lfFolderName');\n        if (input && (FD.form && FD.form.focus || focusId)) {\n          input.focus();\n          if (FD.form && FD.form.focus) { input.select(); FD.form.focus = false; }\n        }\n      }\n\n      // ---------- Menus ----------\n      function cfItems(f) {\n        const items = [];\n        if (f.kind === 'assignment') items.push({ label: 'Open assignment', sub: f.parentTitle, run: () => { window.location.href = avgAssignHref(f.course, f.parentTitle, f.parent); } });\n        // Show in Materials (2026-10-06): the class's Materials, open at the teacher's folder holding it.\n        const show = { label: 'Show in Materials', run: () => { window.location.href = `/course-materials?${avgCourseQ(f.course)}&show=${encodeURIComponent(`${f.kind}:${f.parent}:${f.id}`)}`; } };\n        // Classroom files are already in Google Drive: they open there.\n        if (f.url) {\n          items.push({ label: 'Open in Google Drive', run: () => { if (DRIVE_URL_OK(f.url)) window.open(f.url, '_blank', 'noopener,noreferrer'); } });\n          items.push(show);\n          return items;\n        }\n        items.push(show);\n        // Not for a file that came with an assignment (2026-10-07, Martin): it's the teacher's, already on it.\n        if (!isClassroom() && f.kind !== 'assignment') items.push({ label: 'Attach to an assignment', next: true, run: () => openAttach({ src: 'course', id: f.id, name: f.name, kind: f.kind, parent: f.parent, course: f.course }, f.course) });\n        items.push({ label: 'Download', run: () => { window.location.href = cfDownloadUrl(f); } });\n        if (cfg && cfg.google) items.push({ label: 'Save to Google Drive', run: () => cfSave('gdrive', f) });\n        if (cfg && cfg.microsoft) items.push({ label: 'Save to OneDrive', run: () => cfSave('onedrive', f) });\n        return items;\n      }\n      function itemsFor(e, anchor) {\n        if (e.src === 'course') return cfItems(e.raw);\n        if (e.src === 'gdrive' || e.src === 'onedrive') {\n          const f = e.raw;\n          const list = [{ label: `Open in ${CLOUD[e.src].name}`, run: () => { if (C() && C().linkOk(f.url)) window.open(f.url, '_blank', 'noopener,noreferrer'); } }];\n          if (!isClassroom()) list.push({ label: 'Attach to an assignment', next: true, run: () => openAttach({ src: e.src, id: f.id, name: f.name }, null) });\n          return list;\n        }\n        // Canva: a folder, or a design (from the list or from a folder).\n        const id = String(e.raw.id);\n        if (e.folder) return [\n          { label: 'Open folder', run: () => goFolder(0, { id, name: e.name }) },\n          { label: 'Rename', run: () => { FD.form = { mode: 'rename', id, value: e.name, focus: true }; render(); } },\n        ];\n        const list = [{ label: 'Open in Canva', run: () => openDesign(id, anchor && anchor.closest('[data-lv]')) }];\n        if (!isClassroom()) list.push({ label: 'Attach to an assignment', next: true, run: () => openAttach({ src: 'canva', id, name: e.name }, null) });\n        if (LV.filter === 'canva' && foldersOn()) list.push({ label: 'Move to folder', next: true, run: () => openMoveMenu({ id, name: e.name }) });\n        return list;\n      }\n      function activate(e, el, at) {\n        if (e.src === 'course') { openFxMenu(el, e.name, itemsFor(e, el), at); return; }\n        if (e.src === 'gdrive' || e.src === 'onedrive') { if (C() && C().linkOk(e.raw.url)) window.open(e.raw.url, '_blank', 'noopener,noreferrer'); return; }\n        if (e.folder) { goFolder(0, { id: String(e.raw.id), name: e.name }); return; }\n        openDesign(String(e.raw.id), el);\n      }\n      function openAdd(anchor) {\n        const list = [];\n        ['gdrive', 'onedrive'].forEach(app => {\n          const c = CLOUD[app];\n          if (c.state === 'connect') list.push({ label: `Connect ${c.name}`, run: () => askCloud(app, 'connect') });\n          else if ((c.state === 'ready' || c.state === 'click') && canPick(app)) list.push({ label: `From ${c.name}`, run: () => askCloud(app, 'pick') });\n          else list.push({ label: `From ${c.name}`, soon: true });\n        });\n        if (CV.state === 'connect') list.push({ label: 'Connect Canva', run: () => { window.location.href = `${api}/canva/connect?return_to=${encodeURIComponent('/files')}`; } });\n        list.push({ label: 'Connected apps settings', run: () => { window.location.href = '/settings?section=integrations'; } });\n        openFxMenu(anchor, 'Add files', list);\n      }\n\n      // ---------- Events ----------\n      document.getElementById('fxSearch').addEventListener('input', ev => { LV.query = ev.target.value.trim().toLowerCase(); LV.shown = 60; render(); });\n      fxRoot.addEventListener('submit', ev => {\n        const form = ev.target.closest('[data-folder-form]');\n        if (!form) return;\n        ev.preventDefault();\n        submitFolderForm(form.querySelector('input').value);\n      });\n      fxRoot.addEventListener('input', ev => { if (ev.target.id === 'lfFolderName' && FD.form) FD.form.value = ev.target.value; });\n      fxRoot.addEventListener('click', ev => {\n        const t = ev.target;\n        const filt = t.closest('[data-filter]');\n        if (filt) {\n          LV.filter = filt.dataset.filter; LV.shown = 60;\n          if (LV.filter !== 'canva') FD.form = null;\n          render();\n          return;\n        }\n        const view = t.closest('[data-view]');\n        if (view) { fxView = view.dataset.view; try { localStorage.setItem('schoolagy_files_view', fxView); } catch {} render(); return; }\n        if (t.closest('[data-flash-close]')) { flashState = null; render(); return; }\n        const hideRe = t.closest('[data-reauth-hide]');\n        if (hideRe) { hideReauth(hideRe.dataset.reauthHide); return; }\n        // Google Drive / OneDrive: each opens a window, so nothing is awaited before it.\n        const conn = t.closest('[data-cloud-connect]');\n        if (conn && !conn.disabled) { askCloud(conn.dataset.cloudConnect, 'connect'); return; }\n        const show = t.closest('[data-cloud-show]');\n        if (show && !show.disabled) { askCloud(show.dataset.cloudShow, 'show'); return; }\n        const pick = t.closest('[data-pick-drive]');\n        if (pick && !pick.disabled) { askCloud('gdrive', 'pick'); return; }\n        const pickOne = t.closest('[data-pick-onedrive]');\n        if (pickOne && !pickOne.disabled) { askCloud('onedrive', 'pick'); return; }\n        const retry = t.closest('[data-cloud-retry]');\n        if (retry) { if (cfg) startCloud(retry.dataset.cloudRetry); else loadCloud(); return; }\n        const add = t.closest('[data-lv-add]');\n        if (add) { openAdd(add); return; }\n        if (t.closest('[data-cf-retry]') || t.closest('[data-cf-refresh]')) { loadCourse(true); return; }\n        if (t.closest('[data-lv-showmore]')) { LV.shown += 60; render(); return; }\n        if (t.closest('[data-connect-canva]')) { window.location.href = `${api}/canva/connect?return_to=${encodeURIComponent('/files')}`; return; }\n        if (t.closest('[data-retry-designs]')) { loadCanva(false); return; }\n        if (t.closest('[data-more-designs]')) { loadCanva(true); return; }\n        // Canva folders\n        const crumb = t.closest('[data-crumb]');\n        if (crumb) { goFolder(+crumb.dataset.crumb, null); return; }\n        if (t.closest('[data-folder-new]')) { if (!FD.formBusy) { FD.form = { mode: 'new', value: '', focus: true }; render(); } return; }\n        if (t.closest('[data-folder-cancel]')) { FD.form = null; render(); return; }\n        if (t.closest('[data-folder-retry]')) { loadFolder(false); return; }\n        if (t.closest('[data-folder-more]')) { loadFolder(true); return; }\n        // A file: its ... button, or the file itself.\n        const more = t.closest('[data-lv-more]');\n        if (more) {\n          const e = shownByKey.get(more.dataset.lvMore);\n          if (e) openFxMenu(more, e.name, itemsFor(e, more));\n          return;\n        }\n        const el = t.closest('[data-lv]');\n        if (el) {\n          const e = shownByKey.get(el.dataset.lv);\n          if (e) activate(e, el, el.classList.contains('fx-row') ? { x: ev.clientX, y: ev.clientY } : null);\n        }\n      });\n      fxRoot.addEventListener('contextmenu', ev => {\n        const el = ev.target.closest('[data-lv]');\n        const e = el && shownByKey.get(el.dataset.lv);\n        if (!e) return;\n        ev.preventDefault();\n        openFxMenu(el, e.name, itemsFor(e, el), ev.clientX === 0 && ev.clientY === 0 ? null : { x: ev.clientX, y: ev.clientY });\n      });\n      fxRoot.addEventListener('keydown', ev => {\n        if (ev.key === 'Escape' && FD.form && ev.target.id === 'lfFolderName') { FD.form = null; render(); return; }\n        if (ev.key !== 'Enter' && ev.key !== ' ') return;\n        const row = ev.target.closest('.fx-row[data-lv]');\n        if (!row || ev.target !== row) return;\n        ev.preventDefault();\n        const e = shownByKey.get(row.dataset.lv);\n        if (e) activate(e, row, null);\n      });\n      // The file menu closes like everywhere else on this page.\n      document.addEventListener('click', ev => { if (!fxMenu.hidden && ev.target.isConnected && !fxMenu.contains(ev.target) && !(fxMenuFor && fxMenuFor.contains(ev.target))) closeFxMenu(false); });\n      document.addEventListener('contextmenu', ev => { if (!fxMenu.hidden && !fxMenu.contains(ev.target) && !(fxMenuFor && fxMenuFor.contains(ev.target))) closeFxMenu(false); });\n      document.addEventListener('keydown', ev => { if (ev.key === 'Escape') closeFxMenu(true); });\n      window.addEventListener('resize', () => closeFxMenu(false));\n      window.addEventListener('scroll', () => closeFxMenu(false), true);\n      // Back from Canva's Return button: tidy the address.\n      try {\n        const u = new URL(window.location.href);\n        if (u.searchParams.has('canva')) { u.searchParams.delete('canva'); window.history.replaceState(window.history.state, '', u.pathname + u.search + u.hash); }\n      } catch {}\n      // Signed in or out of a drive in another tab, or a sign-in finished late: show it.\n      window.addEventListener('averages-cloud-change', () => { if (cfg) { startCloud('gdrive'); startCloud('onedrive'); } });\n\n      if (INCOGNITO) {\n        Object.keys(CLOUD).forEach(app => { CLOUD[app].state = 'off'; });\n        CV.state = 'off';\n      }\n      render();\n      loadCourse();\n      if (INCOGNITO) return;\n      loadCloud();\n      loadCanva(false);\n      loadCanvaStatus();\n    }\n    function downloadPlaceholder(f) {\n      const blob = new Blob([`${f.name}\\n\\nSample file from the Averages.io preview.`], { type: 'text/plain' });\n      const a = document.createElement('a');\n      a.href = URL.createObjectURL(blob); a.download = f.name;\n      document.body.appendChild(a); a.click(); a.remove();\n      setTimeout(() => URL.revokeObjectURL(a.href), 1000);\n    }\n    // Materials opens the folder the file is in and highlights it (?file=).\n    function materialsHref(f) {\n      return `/course-materials?${avgCourseQ(f.course)}&file=${encodeURIComponent(f.name)}`;\n    }\n    // Attach to an assignment (2026-10-05): a second menu, in the same spot,\n    // lists open assignments (the file's own course first). Picking one opens\n    // that assignment with the file in Drafts, ready to Submit.\n    const DRIVE_EXT = { doc: 'docx', sheet: 'xlsx', slides: 'pptx' };\n    function fileExt(f) {\n      if (f.src === 'canva') return 'pdf';\n      if (f.src === 'gdrive') return DRIVE_EXT[f.type] || 'docx';\n      const m = f.name.match(/\\.([a-z0-9]+)$/i);\n      return m ? m[1].toLowerCase() : f.type;\n    }\n    function attachHref(f, t) {\n      return avgAssignHref(t.course, t.title, t.id, `&attach=${encodeURIComponent(f.name)}&src=${encodeURIComponent(f.src)}&ext=${encodeURIComponent(fileExt(f))}`);\n    }\n    function attachItems(f) {\n      const list = ATTACH_TARGETS.slice().sort((a, b) => (b.course === f.course) - (a.course === f.course));\n      return list.map(t => {\n        const c = courseOf(t.course);\n        return { label: t.title, sub: `${c ? c.name : 'Course'} · ${t.when}`, run: () => { window.location.href = attachHref(f, t); } };\n      });\n    }\n    const attachItem = f => ({ label: 'Attach to an assignment', next: true, run: () => {\n      if (fxLast) openFxMenu(fxLast.anchor, `Attach \"${f.name}\" to`, attachItems(f), { x: fxLast.x, y: fxLast.y });\n    } });\n    function fileItems(f) {\n      if (f.src === 'course') return [\n        { label: 'Show in Materials', run: () => { window.location.href = materialsHref(f); } },\n        attachItem(f),\n        { label: 'Download', run: () => downloadPlaceholder(f) },\n      ];\n      if (f.src === 'gdrive') return [{ label: 'Open in Google Drive', soon: true }, attachItem(f)];\n      if (f.src === 'onedrive') return [{ label: 'Open in OneDrive', soon: true }, attachItem(f)];\n      return [{ label: 'Open in Canva', soon: true }, attachItem(f)];\n    }\n    function openFile(f, anchor) {\n      if (f.src === 'course') { window.location.href = materialsHref(f); return; }\n      openFxMenu(anchor, f.name, fileItems(f));\n    }\n\n    if (FILES_SIGNED_IN && window.__AVERAGES_MODE__ === 'live') {\n      liveFiles();\n    } else if (FILES_SIGNED_IN) {\n      document.getElementById('fxSide').hidden = true;\n      document.getElementById('fx').style.gridTemplateColumns = 'minmax(0, 1fr)';\n      document.getElementById('fxMain').innerHTML = '<div class=\"fx-empty\"><strong>Files is on the way</strong>Your course files, Google Drive and OneDrive files, and Canva designs will all show up here.</div>';\n      document.getElementById('filesSub').textContent = 'Coming soon';\n    } else {\n      render();\n      document.getElementById('fxSearch').addEventListener('input', e => { fxQuery = e.target.value.trim().toLowerCase(); render(); });\n      document.getElementById('fx').addEventListener('click', e => {\n        const filt = e.target.closest('[data-filter]');\n        if (filt) { fxFilter = filt.dataset.filter; render(); return; }\n        const view = e.target.closest('[data-view]');\n        if (view) { fxView = view.dataset.view; try { localStorage.setItem('schoolagy_files_view', fxView); } catch {} render(); return; }\n        if (e.target.closest('#fxAddDrive')) {\n          openFxMenu(e.target.closest('#fxAddDrive'), 'Add files', [\n            { label: 'From Google Drive', soon: true },\n            { label: 'From OneDrive', soon: true },\n            { label: 'Connected apps settings', run: () => { window.location.href = '/settings'; } },\n          ]);\n          return;\n        }\n        const more = e.target.closest('[data-more]');\n        if (more) { const f = FILES.find(x => x.id === more.dataset.more); if (f) openFxMenu(more, f.name, fileItems(f)); return; }\n        const row = e.target.closest('[data-file]');\n        if (row) { const f = FILES.find(x => x.id === row.dataset.file); if (f) openFile(f, row); }\n      });\n      // Right-click a file (row or tile) for the same menu as its ... button,\n      // opened at the cursor. The keyboard menu key / Shift+F10 has no cursor\n      // point, so it falls back to opening under the file.\n      document.getElementById('fx').addEventListener('contextmenu', e => {\n        const row = e.target.closest('[data-file]');\n        if (!row) return;\n        const f = FILES.find(x => x.id === row.dataset.file);\n        if (!f) return;\n        e.preventDefault();\n        const fromKeyboard = e.clientX === 0 && e.clientY === 0;\n        openFxMenu(row, f.name, fileItems(f), fromKeyboard ? null : { x: e.clientX, y: e.clientY });\n      });\n      document.addEventListener('contextmenu', e => { if (!fxMenu.hidden && !fxMenu.contains(e.target) && !(fxMenuFor && fxMenuFor.contains(e.target))) closeFxMenu(false); });\n      document.getElementById('fx').addEventListener('keydown', e => {\n        if (e.key !== 'Enter' && e.key !== ' ') return;\n        const row = e.target.closest('.fx-row[data-file]');\n        if (!row || e.target !== row) return;\n        e.preventDefault();\n        const f = FILES.find(x => x.id === row.dataset.file); if (f) openFile(f, row);\n      });\n      document.addEventListener('click', e => { if (!fxMenu.hidden && e.target.isConnected && !fxMenu.contains(e.target) && !(fxMenuFor && fxMenuFor.contains(e.target))) closeFxMenu(false); });\n      document.addEventListener('keydown', e => { if (e.key === 'Escape') closeFxMenu(true); });\n      window.addEventListener('resize', () => closeFxMenu(false));\n      window.addEventListener('scroll', () => closeFxMenu(false), true);\n    }\n\n    // Nav: each button goes to its page (same as every other page). The\n    // current page (Files) has no data-href, so clicking it does nothing.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) window.location.href = link.dataset.href;\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/files';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Files';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"files"}
    />
  );
}
